            },
            {
              "name": "ORDER_INPUT_FOLDER",
              "value": "[parameters('orderInputFolder')]"
            },
            {
              "name": "ORDER_APPROVAL_CONTAINER",
              "value": "[parameters('orderApprovalContainer')]"
            },
            {
              "name": "ORDER_APPROVAL_FOLDER",
              "value": "[parameters('orderApprovalFolder')]"
            },
            {
              "name": "ORDER_FULFILMENT_CONTAINER",
              "value": "[parameters('orderFulfilmentContainer')]"
            },
            {
              "name": "ORDER_FULFILMENT_FOLDER",
              "value": "[parameters('orderFulfilmentFolder')]"
            },
            {
              "name": "ORDER_ERROR_CONTAINER",
              "value": "[parameters('orderErrorContainer')]"
            },
            {
              "name": "ORDER_ERROR_FOLDER",
              "value": "[parameters('orderErrorFolder')]"
            },
            {
              "name": "INVENTORY_INPUT_CONTAINER",
              "value": "[parameters('inventoryInputContainer')]"
            },
            {
              "name": "INVENTORY_INPUT_FOLDER",
              "value": "[parameters('inventoryInputFolder')]"
            },
            {
              "name": "INVENTORY_OUTPUT_CONTAINER",
              "value": "[parameters('inventoryOutputContainer')]"
            },
            {
              "name": "INVENTORY_OUTPUT_FOLDER",
              "value": "[parameters('inventoryOutputFolder')]"
            },
            {
              "name": "SHIPMENT_ARCHIVE_CONTAINER",
              "value": "[parameters('shipmentArchiveContainer')]"
            },
            {
              "name": "SHIPMENT_ARCHIVE_FOLDER",
              "value": "[parameters('shipmentArchiveFolder')]"
            },
            {
              "name": "SHIPMENT_OVERSIZE_STATUS_CODE",
              "value": "[parameters('shipmentOversizeStatusCode')]"
            }
          ]
        }
      },
      "dependsOn": [
        "[resourceId('Microsoft.Insights/components', variables('appInsightsName'))]",
        "[resourceId('Microsoft.Storage/storageAccounts/fileServices/shares', variables('storageAccountName'), 'default', variables('contentShareName'))]",
        "[resourceId('Microsoft.Web/serverfarms', variables('planName'))]",
        "[resourceId('Microsoft.Storage/storageAccounts', variables('storageAccountName'))]"
      ]
    },
    {
      "type": "Microsoft.Authorization/roleAssignments",
      "apiVersion": "2022-04-01",
      "scope": "[resourceId('Microsoft.Storage/storageAccounts', variables('storageAccountName'))]",
      "name": "[guid(resourceId('Microsoft.Storage/storageAccounts', variables('storageAccountName')), resourceId('Microsoft.Web/sites', variables('logicAppName')), 'blob-data-contributor')]",
      "properties": {
        "roleDefinitionId": "[subscriptionResourceId('Microsoft.Authorization/roleDefinitions', 'ba92f5b4-2d11-453d-a403-e96b0029c9fe')]",
        "principalId": "[reference(resourceId('Microsoft.Web/sites', variables('logicAppName')), '2024-04-01', 'full').identity.principalId]",
        "principalType": "ServicePrincipal"
      },
      "dependsOn": [
        "[resourceId('Microsoft.Web/sites', variables('logicAppName'))]",
        "[resourceId('Microsoft.Storage/storageAccounts', variables('storageAccountName'))]"
      ]
    },
    {
      "type": "Microsoft.Authorization/roleAssignments",
      "apiVersion": "2022-04-01",
      "scope": "[resourceId('Microsoft.KeyVault/vaults', variables('keyVaultName'))]",
      "name": "[guid(resourceId('Microsoft.KeyVault/vaults', variables('keyVaultName')), resourceId('Microsoft.Web/sites', variables('logicAppName')), 'key-vault-secrets-user')]",
      "properties": {
        "roleDefinitionId": "[subscriptionResourceId('Microsoft.Authorization/roleDefinitions', '4633458b-17de-408a-b874-0445c86b69e6')]",
        "principalId": "[reference(resourceId('Microsoft.Web/sites', variables('logicAppName')), '2024-04-01', 'full').identity.principalId]",
        "principalType": "ServicePrincipal"
      },
      "dependsOn": [
        "[resourceId('Microsoft.KeyVault/vaults', variables('keyVaultName'))]",
        "[resourceId('Microsoft.Web/sites', variables('logicAppName'))]"
      ]
    }
  ],
  "outputs": {
    "logicAppResourceName": {
      "type": "string",
      "value": "[variables('logicAppName')]"
    },
    "storageResourceName": {
      "type": "string",
      "value": "[variables('storageAccountName')]"
    },
    "keyVaultResourceName": {
      "type": "string",
      "value": "[variables('keyVaultName')]"
    }
  }
}
